-- Archive knowledge schema. Generated by go run ./cmd/knowledge-schema.
CREATE TABLE IF NOT EXISTS `knowledge_document_version` (`id` integer PRIMARY KEY AUTOINCREMENT,`source_version_id` integer NOT NULL,`document_id` integer NOT NULL,`archive_id` integer NOT NULL,`title` varchar(255),`sequence` integer,`state` varchar(32),`markdown` TEXT,`summary` TEXT,`summary_state` varchar(32),`digest` varchar(64),`error` varchar(500),`attempts` integer,`lease` varchar(64),`lease_until` integer,`next_run` integer,`updated_at` integer,`summary_model` varchar(255) DEFAULT "",`summary_recipe` varchar(64) DEFAULT "",`parser_revision` varchar(32) DEFAULT "",`index_revision` varchar(32) DEFAULT "",CONSTRAINT `uni_knowledge_document_version_source_version_id` UNIQUE (`source_version_id`));
CREATE INDEX IF NOT EXISTS `idx_knowledge_document_version_state` ON `knowledge_document_version`(`state`);
CREATE INDEX IF NOT EXISTS `idx_knowledge_document_version_archive_id` ON `knowledge_document_version`(`archive_id`);
CREATE INDEX IF NOT EXISTS `idx_knowledge_document_version_document_id` ON `knowledge_document_version`(`document_id`);
CREATE TABLE IF NOT EXISTS `knowledge_document_section` (`id` integer PRIMARY KEY AUTOINCREMENT,`version_id` integer NOT NULL,`position` integer,`heading` varchar(255),`body` TEXT);
CREATE INDEX IF NOT EXISTS `idx_knowledge_document_section_version_id` ON `knowledge_document_section`(`version_id`);
CREATE TABLE IF NOT EXISTS `knowledge_document_workbook` (`version_id` integer,`data` TEXT,PRIMARY KEY (`version_id`));
CREATE TABLE IF NOT EXISTS `knowledge_document_term` (`term` varchar(64),`section_id` integer,`version_id` integer NOT NULL,`weight` integer NOT NULL,PRIMARY KEY (`term`,`section_id`));
CREATE INDEX IF NOT EXISTS `idx_knowledge_document_term_version_id` ON `knowledge_document_term`(`version_id`);
CREATE TABLE IF NOT EXISTS `knowledge_document_derivation` (`section_id` integer,`version_id` integer NOT NULL,`source_digest` varchar(64),`recipe` varchar(64),`model` varchar(255),`state` varchar(32),`content` TEXT,`attempts` integer,`next_run` integer,`error` varchar(500),PRIMARY KEY (`section_id`));
CREATE INDEX IF NOT EXISTS `idx_knowledge_document_derivation_version_id` ON `knowledge_document_derivation`(`version_id`);
